        #region Mutagen
        public IEnumerable<IFormLinkGetter> EnumerateFormLinks(IProjectileGetter obj, bool iterateNestedRecords = true)
        {
            foreach (var item in base.EnumerateFormLinks(obj, iterateNestedRecords))
            {
                yield return item;
            }
            if (obj.Keywords is {} KeywordsItem)
            {
                foreach (var item in KeywordsItem)
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            if (obj.Model is {} ModelItems)
            {
                foreach (var item in ModelItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            if (obj.Destructible is {} DestructibleItems)
            {
                foreach (var item in DestructibleItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            if (FormLinkInformation.TryFactory(obj.SpeedCurveTable, out var SpeedCurveTableInfo))
            {
                yield return SpeedCurveTableInfo;
            }
            if (FormLinkInformation.TryFactory(obj.SeekStrengthCurveTable, out var SeekStrengthCurveTableInfo))
            {
                yield return SeekStrengthCurveTableInfo;
            }
            yield return FormLinkInformation.Factory(obj.Light);
            yield return FormLinkInformation.Factory(obj.MuzzleFlashLight);
            yield return FormLinkInformation.Factory(obj.Explosion);
            yield return FormLinkInformation.Factory(obj.Sound);
            yield return FormLinkInformation.Factory(obj.SoundCountdown);
            yield return FormLinkInformation.Factory(obj.SoundDisable);
            yield return FormLinkInformation.Factory(obj.DefaultWeaponSource);
            yield return FormLinkInformation.Factory(obj.DecalData);
            yield return FormLinkInformation.Factory(obj.CollisionLayer);
            yield return FormLinkInformation.Factory(obj.VATSProjectile);
            yield break;
        }
        
